#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────────────────
# ALTER XIV — SELF-CONTAINED SCAFFOLD BOOTSTRAP
# Recreates the full alter-xiv monorepo (118 files) in place. No external deps
# except python3 (standard on any dev machine). No network, no Drive, no zip needed.
#
# USAGE (run from wherever you want the scaffold to live, e.g. your repo root):
#     bash bootstrap-alter-xiv.sh
# Optional target dir:
#     bash bootstrap-alter-xiv.sh /path/to/dir
# ─────────────────────────────────────────────────────────────────────────────
set -e
OUT="${1:-.}"
TMP="$(mktemp)"
echo "Decoding Alter XIV scaffold..."
cat > "$TMP" << 'PAYLOAD'

PAYLOAD
python3 - "$TMP" "$OUT" << 'PY'
import base64, zipfile, io, sys
raw = open(sys.argv[1]).read()
data = base64.b64decode(raw)
zipfile.ZipFile(io.BytesIO(data)).extractall(sys.argv[2])
print("Extracted scaffold.")
PY
rm -f "$TMP"
echo ""
echo "✅ Alter XIV scaffold created at: $OUT/alter-xiv"
echo "   Sanity check:"
ls "$OUT/alter-xiv" >/dev/null 2>&1 && echo "   - $(find "$OUT/alter-xiv" -type f | wc -l) files written"
echo ""
echo "NEXT: open $OUT/alter-xiv as the working directory and tell Claude Code:"
echo "      \"Follow KICKOFF.md and begin building.\""
